/**
 * A live draw behind the topology builder, for the Add playoffs stories — the shape TMX's inline topology has.
 *
 * The draw is real: generated by the factory, its offers read from `getAvailablePlayoffProfiles`, and a chosen chip
 * attached through `generateAndPopulatePlayoffStructures` + `attachPlayoffStructures`, exactly as the Add playoffs
 * dialogs do. After each attach the topology is loaded again FROM THE DRAW, never edited in place, so what the story
 * shows next is what the record now says.
 *
 * `hydrate` is the least a story needs to draw the structures and their links. TMX's `hydrateTopology` is the full
 * version (qualifying positions, team lines, composite types); this is not a second copy of it to keep in step, only
 * enough for a round robin with elimination playoffs.
 */
import {
  playoffGenerationParams,
  playoffOffersByStructure
} from '../../components/topology-builder/domain/playoffOffers';
import { TopologyBuilderControl } from '../../components/topology-builder/controller/topologyBuilderControl';
import { mocksEngine, tournamentEngine, drawDefinitionConstants } from 'tods-competition-factory';

import type { PlayoffOffer, TopologyEdge, TopologyNode, TopologyState } from '../../components/topology-builder/types';

const { CONTAINER, ROUND_ROBIN, SINGLE_ELIMINATION } = drawDefinitionConstants;

export type LiveTopologyHost = {
  element: HTMLElement;
  control: TopologyBuilderControl;
  /** Every structure's name, in the draw's order. */
  structureNames: () => string[];
  /** The chips the live draw offers for a structure, by name. */
  offersFor: (structureName: string) => string[];
  added: string[];
};

/** A 32-entry round robin in groups of four, with a 1-16 playoff: the draw CA was working with on 2026-11-07. */
export function liveTopologyHost({
  mode,
  height = '100vh'
}: { mode?: 'view' | 'addPlayoffs'; height?: string } = {}): LiveTopologyHost {
  const generated: any = mocksEngine.generateTournamentRecord({
    drawProfiles: [
      {
        drawSize: 32,
        drawType: 'ROUND_ROBIN_WITH_PLAYOFF',
        structureOptions: {
          groupSize: 4,
          playoffGroups: [{ finishingPositions: [1, 2], structureName: 'Playoff 1-16' }]
        }
      }
    ]
  });
  tournamentEngine.setState(generated.tournamentRecord);
  const drawId: string = generated.drawIds[0];
  const drawDefinition = () => tournamentEngine.getEvent({ drawId }).drawDefinition;

  // The host caches the draw's answer and asks again only after it changes the draw (TopologyBuilderConfig).
  let offers = new Map<string, PlayoffOffer[]>();
  const readOffers = () => {
    offers = playoffOffersByStructure(
      tournamentEngine.getAvailablePlayoffProfiles({ drawId }).availablePlayoffProfiles
    );
  };
  readOffers();

  const added: string[] = [];
  const element = document.createElement('div');
  // The host sizes the layout and the canvas fills it, as TMX's inline topology fills the window (CA, 2026-11-08)
  element.style.height = height;

  const control = new TopologyBuilderControl({
    initialState: hydrate(drawDefinition()),
    hideTemplates: true,
    readOnly: true,
    footer: true,
    mode,
    playoffOffers: (node) => offers.get(node.id),
    onAddPlayoff: (node, offer) => {
      const structureName = `Playoff ${offer.finishingPositionRange}`;
      const playoffs: any = tournamentEngine.generateAndPopulatePlayoffStructures({
        drawId,
        structureId: node.id,
        ...(playoffGenerationParams(offer, structureName) as any)
      });
      if (playoffs.error) throw new Error(playoffs.error.message);
      const attached: any = tournamentEngine.attachPlayoffStructures({
        drawId,
        structures: playoffs.structures,
        links: playoffs.links,
        matchUpModifications: playoffs.matchUpModifications
      });
      if (!attached.success) throw new Error(attached.error?.message ?? 'attach failed');
      added.push(structureName);
      readOffers();
      control.loadState(hydrate(drawDefinition()) as TopologyState);
      control.autoLayout();
    }
  });
  control.render(element);
  control.autoLayout();

  const structureByName = (name: string) => drawDefinition().structures.find((s: any) => s.structureName === name);
  return {
    element,
    control,
    added,
    structureNames: () => drawDefinition().structures.map((s: any) => s.structureName),
    offersFor: (name) => (offers.get(structureByName(name)?.structureId) ?? []).map((o) => o.finishingPositionRange)
  };
}

function hydrate(drawDefinition: any): Partial<TopologyState> {
  const positions = (structure: any): number =>
    structure.structureType === CONTAINER
      ? structure.structures.reduce((total: number, group: any) => total + positions(group), 0)
      : (structure.positionAssignments?.length ?? 0);

  const nodes: TopologyNode[] = drawDefinition.structures.map((structure: any) => {
    const isRoundRobin = structure.structureType === CONTAINER;
    return {
      id: structure.structureId,
      structureName: structure.structureName,
      stage: structure.stage,
      structureType: isRoundRobin ? ROUND_ROBIN : SINGLE_ELIMINATION,
      drawSize: positions(structure),
      ...(isRoundRobin && { structureOptions: { groupSize: positions(structure.structures[0]) } }),
      position: { x: 0, y: 0 }
    };
  });

  const edges: TopologyEdge[] = (drawDefinition.links ?? []).map((link: any, index: number) => {
    const byPosition = !!link.source?.finishingPositions?.length;
    return {
      id: `link-${index}`,
      sourceNodeId: link.source.structureId,
      targetNodeId: link.target.structureId,
      linkType: byPosition ? 'POSITION' : link.linkType,
      ...(byPosition
        ? { finishingPositions: link.source.finishingPositions }
        : { sourceRoundNumber: link.source.roundNumber }),
      targetRoundNumber: link.target?.roundNumber,
      label: byPosition ? `positions ${link.source.finishingPositions.join(',')}` : `R${link.source.roundNumber} loser`
    };
  });

  return { drawName: drawDefinition.drawName ?? 'Live draw', nodes, edges, selectedNodeId: null, selectedEdgeId: null };
}
